    <property name="title">enoobis.ru</property>
    <property name="default-width">250</property>
    <property name="default-height">200</property>

    <child>
        <object class="GtkSpinButton" id="button">

          <property name="orientation">Orientation.VERTICAL</property>

          <property name="halign">GTK_ALIGN_START</property>
          <property name="valign">GTK_ALIGN_START</property>
          <property name="climb-rate">1.0</property>
          <property name="digits">0</property>
          <property name="adjustment">
            <object class="GtkAdjustment">
              <property name="lower">0.0</property>
              <property name="page-increment">5.0</property>
              <property name="page-size">0.0</property>
              <property name="step-increment">1.0</property>
              <property name="upper">100.0</property>
              <property name="value">50.0</property>
            </object>
          </property>
        </object>
    </child>
  </object>
</interface>
```

![направление виджета spinbutton в gtk и c#](/uploads/course-lectures/1c6e54a8b29868e8dcdd90c0ad1cd103a1902c9a.png)

Списки и ListBox

Для работы со списками данных GTK предоставляет ряд специальных виджетов для работы. Эти виджеты позволяют отобразить множество объектов унифицированным образом, причем диапазон элементов в списке может вариироваться от 2-3 элементов до сотен тысяч элементов. Подобные виджеты могут отображать как статичные неизменяющиеся данные, так и данные, которые подверженые изменению - либо при добавлении/удалении элементов в списке, либо при редактировании уже существующих элементов.

Самым простым и в тже время распространенным виджетом для отображения списка является класс **ListBox**. Он представляет вертикальный список, где каждый элемент представлен объектом типа **ListBoxRow** - своего рода строкой. Эти строки можно динамически сортировать и фильтровать, осуществлять по строкам навигацию и выбор с помощью клавиатуры и мыши.

Хотя `ListBox` должен иметь только дочерние элементы ListBoxRow, в него можно добавить любой виджет, тогда он неявно будет обернут в `ListBoxRow`.

Для создания виджета применяется статический метод `ListBox.New()` без параметров:

```c#
ListBox listBox = ListBox.New();
```

### Добавление элементов

Для добавления элементов в ListBox применяется ряд функций:

- Append(Widget child) : добавляет виджет в конец списка

- Prepend(Widget child) : добавляет виджет в начало списка

- Insert(Widget child, int position) : вставляет указанный виджет на определенную позицию в списке

Обратите внимание, что в любом случае добавляемый элемент должен представлять виджет. Рассмотрим применение этих функций:

```c#
using Gtk;

var app= Application.New("com.enoobis", Gio.ApplicationFlags.DefaultFlags);

app.OnActivate += (sender, _) =>
{
    var window = new Window();
    window.Title = "enoobis.ru";
    window.DefaultWidth = 250;
    window.DefaultHeight = 200;

    ListBox listBox = ListBox.New();

    // добавляем в конец списка
    listBox.Append(Label.New("C++"));
    listBox.Append(Label.New("Python"));
    // добавляем в начало списка
    listBox.Prepend(Label.New("C#"));
    // вставляем по индексу 1 (то есть второй элемент)
    listBox.Insert(Label.New("JavaScript"), 1);

    window.Child = listBox;
    window.Application = (Application) sender;
    window.Show();
};

app.RunWithSynchronizationContext(null);
```

Здесь все добавляемые элементы представляют метки `Label` с некоторым текстом. В итоге мы получим следующий список:

![список listbox в gtk и c#](/uploads/course-lectures/d937c9d84243047d2ddd7dfe0a4f248568db3836.png)

Но, как можно увидеть из скриншота, по умолчанию ListBox растягивается по всей ширине/высоте окна-контейнера, и, кроме того, растягиваются и добавляемые метки. В итоге мы получаем растянутые метки с текстом по центру виджета. Чтобы должным образом упорядочить виджеты, мы можем использовать стандартные способы позиционирования, в частности, свойства `Halign` и `Valign`. Например:

```c#
using Gtk;

var app= Application.New("com.enoobis", Gio.ApplicationFlags.DefaultFlags);

app.OnActivate += (sender, _) =>
{
    var window = new Window();
    window.Title = "enoobis.ru";
    window.DefaultWidth = 250;
    window.DefaultHeight = 200;

    ListBox listBox = ListBox.New();

    string[] langs = {"C#", "C++", "JavaScript", "Python"};
    foreach(var lang in langs){
        Label label = Label.New(lang);
        label.Halign = Align.Start; // выравнивание по левому краю
        listBox.Append(label);
    }

    window.Child = listBox;
    window.Application = (Application) sender;
    window.Show();
};

app.RunWithSynchronizationContext(null);
```

![добавление элементов в список listbox в gtk и c#](/uploads/course-lectures/e778700d8a68dddf03d2182e54c49480f22f7204.png)

### Получение элементов

Для получения элементов списка класс ListBox предоставляет пару методов:

- ListBoxRow? GetRowAtIndex(int index) получает элемент в списке по индексу index. Если index_ отрицателен или больше количества элементов в списке, возвращается NULL.

- ListBoxRow? GetRowAtY(int y) получает строку в позиции y.

Обратите внимание, что каждая из этих методов возвращает объект типа **ListBoxRow**, в который оборачивается добавляемый виджет. Однако этот тип имеет метод **GetChild()**, который позволяет получить непосредственно содержимое в виде объекта `Widget?`.

Для примера просто выведем все элементы из списка на консоль сразу после его создания:

```c#
#using Gtk;

var app= Application.New("com.enoobis", Gio.ApplicationFlags.DefaultFlags);

app.OnActivate += (sender, _) =>
{
    var window = new Window();
    window.Title = "enoobis.ru";
    window.DefaultWidth = 250;
    window.DefaultHeight = 200;

    ListBox listBox = ListBox.New();

    string[] langs = {"C#", "C++", "JavaScript", "Python"};
    foreach(var lang in langs){
        Label label = Label.New(lang);
        label.Halign = Align.Start; // выравнивание по левому краю
        listBox.Append(label);
    }

    ListBoxRow? row;
    int i = 0;
    // пока есть строки, получаем их в переменную row
    while((row = listBox.GetRowAtIndex(i++)) is not null){

        // получаем содержимое строки - выше добавленные метки
        Label? label = (Label?) row.GetChild();
        Console.WriteLine($"Row {i}: {label?.Label_}");
    }
    window.Child = listBox;
    window.Application = (Application) sender;
    window.Show();
};

app.RunWithSynchronizationContext(null);
```

В итоге консоль выведет:

```bash
Row 1: C#
Row 2: C++
Row 3: JavaScript
Row 4: Python
```

### Удаление элементов

Для удаления строк GTK предоставляет ряд функций:

- void Remove(Widget child) удаляет дочерний элемент, который передается через второй параметр.

- void RemoveAll() удаляет все строки из виджета

Например, удаление второй строки (с индексом 1):

```c#
ListBox listBox = ListBox.New();

string[] langs = {"C#", "C++", "JavaScript", "Python"};
foreach(var lang in langs){
    Label label = Label.New(lang);
    label.Halign = Align.Start; // выравнивание по левому краю
    listBox.Append(label);
}

// удаление второй строки
ListBoxRow? row = listBox.GetRowAtIndex(1);
if (row is not null) listBox.Remove(row);
```

### Выделение строк

Для выбора строк и получения выбранных строк виджет ListBox предоставляет ряд методов:

- ListBoxRow? GetSelectedRow() возвращает выбранную строку или NULL, если не выбрано ни одной строки.

- gtk_list_box_get_selected_rows возвращает список всех выбранных строк

- void SelectAll() выбирает все строки

- void SelectRow(ListBoxRow? row) выбирает определенную строку

- void SelectedForeach(ListBoxForeachFunc func) выполняет для всех выбранных строк метод, который представляет делегат ListBoxForeachFunc

- void UnselectAll() отменяет выбор всех выбранных строк

- void UnselectRow(ListBoxRow row) отменяет выбор одной строки

Например, выбор второй строки:

```c#
ListBox listBox = ListBox.New();

//..................................

ListBoxRow? row = listBox.GetRowAtIndex(1);
listBox.SelectRow(row);
```

Другой пример - получим выделенную строку. Для этого определим простейшее приложение:

```c#
using Gtk;

var app= Application.New("com.enoobis", Gio.ApplicationFlags.DefaultFlags);

var label = Label.New(null); // метка для вывода выбранного элемента
var listBox = ListBox.New();

app.OnActivate += (sender, _) =>
{
    var window = new Window();
    window.Title = "enoobis.ru";
    window.DefaultWidth = 250;
    window.DefaultHeight = 200;

    // наполняем список
    string[] langs = {"C#", "C++", "JavaScript", "Python"};
    foreach(var lang in langs){
        Label label = Label.New(lang);
        label.Halign = Align.Start;
        listBox.Append(label);
    }
    listBox.Valign = Align.Start;

    label.Halign = Align.Start;
    label.Valign = Align.Start;

    Button button = Button.NewWithLabel("Get");
    button.Halign = Align.Start;
    button.OnClicked += SelectLang;

    Box box =  Box.New(Orientation.Vertical, 10);

    box.Append(label);
    box.Append(button);
    box.Append(listBox);

    window.Child = box;
    window.Application = (Application) sender;
    window.Show();
};

app.RunWithSynchronizationContext(null); 

// обработчик нажатия кнопки
void SelectLang(Button sender, EventArgs e) {

    // получаем выбранную строку
    ListBoxRow? selected = listBox.GetSelectedRow();
    // получаем метку из выбранной строки
    Label? rowLabel = (Label?) selected?.GetChild();
    // получаем текст на метке из выбранной строки и передаем его на верхней метке
    label.Label_ = rowLabel?.Label_;
}
```

В данном случае при нажатии на кнопку в обработчике события нажатия - методе SelectLang получаем выбранную строку и передаем ее текст на метку выше списка:

![выбор строк в списке listbox в gtk и c#](/uploads/course-lectures/1479e69f154ddde22183da0ae88e06b5a85ade3a.png)

### Настройка выбора строк

По умолчанию пользователь может выбрать только одну строку, но с помощью свойства **SelectionMode** можно настроить этот аспект. Данное свойство представляет значение перечисления **SelectionMode**, которое может принимать следующие значения:

- None : выбор невозможен. Значение: 0

- Single : можно выбрать только один элемент или ноль элементов. Значение: 1

- Browse : можно выбрать ровно один элемент. Значение: 2

- Multiple : доступен выбор множества строк. Значение: 3

Например, установка возможности выбора нескольких строк:

```brush
var listBox = ListBox.New();
listBox.SelectionMode = SelectionMode.Multiple;
```

### Получение всех выбранных строк

Даже если мы установили множественный выбор и можем выбрать одномоментно сразу несколько строк, то встает вопрос, как получить все эти строки, тем более что класс ListBox не предоставляет для этого специального свойства или метода. Но в качестве решения мы можем использовать метод **SelectedForeach()**, который в качестве параметра принимает метод, соответствующий делегату `ListBoxForeachFunc`. Данный делегат принимает два параметра:

```c#
public delegate void ListBoxForeachFunc(ListBox box, ListBoxRow row)
```

Первый параметр представляет сам список ListBox, а второй - выбранную строку `ListBoxRow`.

И при выполнении **SelectedForeach()** будет выполнять переданный ему метод-делегат ListBoxForeachFunc для каждой выбранной строки. Выбранные строки будут передаваться в качестве второго параметра.

Например, установим множественный выбор и выведем на консоль все выбранные строки:

```c#
using Gtk;

var app= Application.New("com.enoobis", Gio.ApplicationFlags.DefaultFlags);

var listBox = ListBox.New();

app.OnActivate += (sender, _) =>
{
    var window = new Window();
    window.Title = "enoobis.ru";
    window.DefaultWidth = 250;
    window.DefaultHeight = 200;

    // наполняем список
    string[] langs = {"C#", "C++", "JavaScript", "Python"};
    foreach(var lang in langs){
        Label label = Label.New(lang);
        label.Halign = Align.Start;
        listBox.Append(label);
    }
    listBox.Valign = Align.Start;
    listBox.SelectionMode = SelectionMode.Multiple;

    Button button = Button.NewWithLabel("Selected");
    button.Halign = Align.Start;
    button.OnClicked += GetSelectedLangs; // обрабатываем все выделенные строки

    Box box =  Box.New(Orientation.Vertical, 10);

    box.Append(button);
    box.Append(listBox);

    window.Child = box;
    window.Application = (Application) sender;
    window.Show();
};

app.RunWithSynchronizationContext(null); 

// обработчик нажатия кнопки
void GetSelectedLangs(Button sender, EventArgs e) {

    listBox.SelectedForeach(PrintLang);
}

void PrintLang(ListBox _, ListBoxRow selectedRow){
    // получаем метку из выбранной строки
    Label? rowLabel = (Label?) selectedRow.GetChild();
    // получаем текст на метке из выбранной строки
    Console.WriteLine(rowLabel?.Label_);
}
```

Здесь по нажатию на кнопку будет срабатывать метод-обработчик GetSelectedLangs, который выполняет метод `listBox.SelectedForeach()`. В этот метод передается другой метод - PrintLang, который соответствует делегату ListBoxForeachFunc. В PrintLang получаем выбранную строку и выводим ее текст на консоль.

### Обработка выбора и активации строки

Чтобы строку можно было выбрать или нажать на нее, соответствующий элемент `ListBoxRow` можно пометить как активируемый или выбираемый. Для этой цели класс `ListBoxRow` предоставляет соответственно методы **SetActivatable(bool)** и **SetSelectable(bool)**, которые в принципе однотипны и в качестве второго параметра принимают булевое значение `true` или `false`.

Если строка активируемая, и пользователь нажимает на нее, то для нее ListBox сгенерирует событие **OnRowActivated**:

```c#
event SignalHandler<ListBox, ListBox.RowActivatedSignalArgs> OnRowActivated
```

Второй параметр представляет нажатую строку, а третий параметр - передаваемые в обработчик сигнала данные. Например, выведем текст нажатой строки в метку:

```c#
using Gtk;

var app= Application.New("com.enoobis", Gio.ApplicationFlags.DefaultFlags);

var label = Label.New(null);
var listBox = ListBox.New();

app.OnActivate += (sender, _) =>
{
    var window = new Window();
    window.Title = "enoobis.ru";
    window.DefaultWidth = 250;
    window.DefaultHeight = 200;

    // наполняем список
    string[] langs = {"C#", "C++", "JavaScript", "Python"};
    foreach(var lang in langs){
        Label label = Label.New(lang);
        label.Halign = Align.Start;
        listBox.Append(label);
    }
    listBox.Valign = Align.Start;
    listBox.OnRowActivated += GetSelectedLang;

    label.Halign = Align.Start;

    Box box =  Box.New(Orientation.Vertical, 10);

    box.Append(label);
    box.Append(listBox);

    window.Child = box;
    window.Application = (Application) sender;
    window.Show();
};

app.RunWithSynchronizationContext(null); 

// обработчик нажатия кнопки
void GetSelectedLang(ListBox sender, ListBox.RowActivatedSignalArgs e) {

    ListBoxRow? row = e.Row; // получаем выбранную строку
    Label? rowLabel = (Label?) row?.GetChild();
    label.Label_ = rowLabel?.Label_;
}
```

В данном случае за обработку события OnRowActivated отвечает метод GetSelectedLang, в который в качестве второго параметра передаются аргументы события в виде объекта `ListBox.RowActivatedSignalArgs`. Через свойство `Row` этого объекта мы можем получить выбранную строку, для которой было сгенерировано событие, и далее получить ее текст и вывести его на текстовой метке:

![обработка нажатия на строку в списке listbox в gtk и c#](/uploads/course-lectures/37e4a3231e87504bcb9aa0fe54b76e72206b7edc.png)

Если строка выбираемая (как это происходит по умолчанию), то строка будет помечена как выбранная, когда пользователь попытается ее выбрать, а ListBox сгенерирует событие **OnRowSelected**:

```c#
event SignalHandler<ListBox, ListBox.RowSelectedSignalArgs> OnRowSelected
```

Здесь аналогичное событие, только в этом случае пользователь может отменить выбор, и параметр row в этом случае будет равен `null`

### Сортировка

Класс **ListBox** предоставляет функционал для сортировки элементов в виде метода **SetSortFunc()**

```c#
public void SetSortFunc(ListBoxSortFunc? sortFunc)
```

В качестве параметра в метод передается делегат **ListBoxSortFunc : ```c#
public delegate int ListBoxSortFunc(ListBoxRow row1, ListBoxRow row2)
``` Метод, который соответствует этому делегату, получает две сравниваемые строки ListBoxRow и возвращает число: если первая строка "больше" второй, то возвращается 1, если "меньше", то -1. Если далее потребуется отменить результаты сортировки, то применяется метод без параметров InvalidateSort()**.

Причем сортировка идет динамически, даже если строки меняют свое содержимое. Например:

```c#
using Gtk;

var app= Application.New("com.enoobis", Gio.ApplicationFlags.DefaultFlags);

app.OnActivate += (sender, _) =>
{
    var window = new Window();
    window.Title = "enoobis.ru";
    window.DefaultWidth = 250;
    window.DefaultHeight = 200;

    var listBox = ListBox.New();

    // устанавливаем функцию сортировки
    listBox.SetSortFunc(SortList);

    // наполняем список
    string[] langs = {"Python", "C++", "JavaScript", "C#"};
    foreach(var lang in langs){
        Label label = Label.New(lang);
        label.Halign = Align.Start;
        listBox.Append(label);
    }

    window.Child = listBox;
    window.Application = (Application) sender;
    window.Show();
};

app.RunWithSynchronizationContext(null); 

// метод для сортировки
int SortList(ListBoxRow row1, ListBoxRow row2){

    Label? row1Label = (Label?) row1.GetChild();
    Label? row2Label = (Label?) row2.GetChild();
    string row1Text = row1Label?.Label_?? "";
    string? row2Text = row2Label?.Label_;

    // сравниваем в лексикографическом порядке
    return row1Text.CompareTo(row2Text);
}
```

В данном случае сортировка производится в функции SortList, где сравниваем текст строк с помощью метода `CompareTo()`, который определяется строками при реализации встроенного интерфейса `IComparable`. Таким образом, строки будут автоматически сортироваться:

![сортировка списка listbox в gtk и c#](/uploads/course-lectures/918da43103b0a4728e9f6b797c8ac907b8a0ba22.png)

### Фильтрация

**ListBox** также позволяет отфильтровать элементы - для этого применяется метод **SetFilterFunc()**

```c#
public void SetFilterFunc(ListBoxFilterFunc? filterFunc)
```

В качестве параметра метод принимает метод типа делегата **ListBoxFilterFunc ```c#
public delegate bool ListBoxFilterFunc(ListBoxRow row)
``` Метод, который соответствует этому делегату, получает строку ListBoxRow и проверяет ее на соответствие некоторому условию. Если строка соответствует условию, то метод возвращает true , иначе возвращается false . Если далее потребуется отменить результаты фильтрации, то применяется метод без параметров InvalidateFilter()**.

Рассмотрим небольшой пример:

```c#
using Gtk;

var app= Application.New("com.enoobis", Gio.ApplicationFlags.DefaultFlags);

string term = "";  // критерий фильтрации
var listBox = ListBox.New();

app.OnActivate += (sender, _) =>
{
    var window = new Window();
    window.Title = "enoobis.ru";
    window.DefaultWidth = 250;
    window.DefaultHeight = 200;

    //listBox.Valign = Align.Start;
    // наполняем список
    string[] langs = {"C", "Python", "C++", "C#", "JavaScript", "Java"};
    foreach(var lang in langs){
        Label label = Label.New(lang);
        label.Halign = Align.Start;
        listBox.Append(label);
    }


    Entry entry = Entry.New(); // текстовое поле для ввода критерия фильтрации
    // подключаем обработчик ввода текста
    Editable.Text_PropertyDefinition.Notify(
        sender: entry,
        signalHandler: OnTextChanged
    );

    Box box =  Box.New(Orientation.Vertical, 10);

    box.Append(entry);
    box.Append(listBox);

    window.Child = box;
    window.Application = (Application) sender;
    window.Show();
};

app.RunWithSynchronizationContext(null); 

// функция фильтрации
bool FilterList(ListBoxRow row){

    Label? rowLabel = (Label?) row.GetChild();
    // если текст в строке содержит значение term, то true
    string rowText = rowLabel?.Label_ ?? "";
    return rowText.Contains(term);
}

void OnTextChanged(GObject.Object sender, GObject.Object.NotifySignalArgs e)
{
    // получаем текст из текстового поля и устанавливаем значение term
    Entry entry = (Entry) sender;
    term = entry?.Text_ ?? "";
    // устанавливаем функцию фильтрации
    listBox.SetFilterFunc(FilterList);
}
```

В данном случае интерфейс представлен элементом Box, который содержит текстовое поле Entry для ввода ключа фильтрации и собственно фильтруемый список ListBox. При каждом вводе в текстовое поле будет срабатывать метод `OnTextChanged`

```c#
void OnTextChanged(GObject.Object sender, GObject.Object.NotifySignalArgs e)
{
    // получаем текст из текстового поля и устанавливаем значение term
    Entry entry = (Entry) sender;
    term = entry?.Text_ ?? "";
    // устанавливаем функцию фильтрации
    listBox.SetFilterFunc(FilterList);
}
```

Здесь мы получаем введенный в текстовое поле текст и на его основе устанавливаем критерий фильтрации - строку term. И затем устанавливаем функцию фильтрации. Стоит отметить, что несмотря на то, что здесь функция фильтрации НЕ меняется вне зависимости от введенных значений - меняется только значение term, но нам все равно надо переустанавливать ее, по сути это и приведет к срабатыванию фильтрации.

В функции фильтрации - `FilterList` проверяем, имеет ли метка строки в списке введенный текст:

```c#
bool FilterList(ListBoxRow row){

    Label? rowLabel = (Label?) row.GetChild();
    // если текст в строке содержит значение term, то true
    string rowText = rowLabel?.Label_ ?? "";
    return rowText.Contains(term);
}
```

![фильтрация списка listbox в gtk и c#](/uploads/course-lectures/ae105895d4bd583870ba21e6e3ce1b5c88be91c5.png)

В прошлых статьях было рассмотрено, как работать с элементами списка в видежте **ListBox** как с отдельными виджетами. Но для управления данными, особенно большими наборами однотипных данными предпочтительнее использовать **Gio.ListModel** или грубо говоря **модель**. **Gio.ListModel** представляет изменяемый список объектов `GObject.Object`. Хотя этот тип служит моделью для виджета ListBox и других списочных виджетов, но его также можно использовать как удобный способ возврата списков данных с поддержкой обновлений.

При этом сам тип **ListModel** представляет лишь интерфейс. Но в GTK существуют уже готовые типы моделей как конкретных ситуаций, например **DirectoryList** или **StringList**. Также существуют общие реализации моделей списков, такие как **ListStore**, которые позволяют создавать списки произвольных объектов. Но при необходимости разработчики могут создавать и свои собственные типы моделей, заточенные под какие-то специфические ситуации.

К основным моделям стоит отнести следующие:

- ListStore : в ее основе лежит сбалансированное дерево (balanced tree). Достаточно хорошо работает для наборов данных размером в диапазоне 0-1 000 000 и может обрабатывать вставки и удаления. Использует кэшированный итератор для ускорения линейного доступа к элементам.

- StringList : может обрабатывать только строки. В ее основе - динамически выделяемый массив. StringList хорошо подходит для любого места, где в противном случае использовался бы тип string , и лучше всего работает, если набор данных не очень динамичен.

- DirectoryList : она работает поверх объекта ListModel и асинхронно заполняет его данными типа File .

Если эти модели не соответствуют нужному варианту использования или требованиям масштабируемости, можно создать собственную реализацию **ListModel**. Это небольшой интерфейс, и его не очень сложно реализовать.

### Элементы модели

Каждый элемент в модели, то есть непосредственно отображаемые данные, представляет объект **GObject.Object**. При этом все элементы в ListModel имеют один и тот же тип (или являются производными от него). Каждый элемент в модели имеет позицию, которая является беззнаковым целым числом, описывающим, где в модели находится элемент. Первый элемент в модели находится в позиции 0. Позиция элемента может меняться по мере добавления или удаления других элементов из модели. Важно понимать разницу между элементами и позициями, поскольку сопоставление позиции элементу не является постоянным, что важно учитывать при отслеживании элементов по позиции при работе с моделями.

Каждый объект в списке может также сообщать об своих изменениях через некоторый механизм (обычно метод `GObject.Object.Notify`). А посредством метода `ItemsChanged` модель ListModel может уведомлять систему о произошедших изменениях среди элементов, таких как добавление или удаление элементов.

### Фабрика

Другая важная часть виджетов-списков — это фабрика. Каждая фабрика представляет собой реализацию ListItemFactory . Фабрика отвечает за сопоставление элементов модели с виджетами. Для это при отображении для каждого элемента создается объект ListItem . Для различных ситуаций есть различные типы фабрик.

### Модель выбора и активация

Виджеты поддерживают выбор элементов через **модель выбора (selection model)**. Модель выбора — это реализация интерфейса SelectionModel поверх интерфейса ListModel, которая позволяет отмечать каждый элемент в модели как выбранный или невыбранный. Как и обычные модели, это можно реализовать либо путем прямой реализации SelectionModel, либо использования одной из моделей GTK, предоставленных для этих целей, например классы **NoSelection** или **SingleSelection**.

Модель выбора определяет процесс выбора элементов: можно выбирать только один элемент или же поддерживается множественный выбор. Состояние выбора элемента можно получить через свойство **Selected** объекта ListItem.

Семантика ListModel близка к семантике массива: **GetNItems()()** возвращает количество элементов в списке, а **GetItem(uint position)** возвращает элемент в позиции (от 0). Кроме того, с помощью функции **GetItemType()** можно получить тип элементов. Тип может быть интерфейсом, в этом случае все объекты в списке должны его реализовывать.

### Производительность

Для коротких списков могут создаваться экземпляры виджетов для каждого элемента в модели. Однако в случае с большими моделями (до тысяч или миллионов элементов) или по мере разрастания модели это становится менее осуществимым. Из-за этого списочные виджеты создают только ограниченное количество элементов списка и повторно используют их, привязывая к новым элементам. В целом виджеты-представления пытаются сохранить элементы списка доступными только для тех элементов, которые фактически можно увидеть на экране.

Хотя такое поведение позволяет представлениям легко масштабироваться до огромных списков, оно накладывает ряд ограничений. Например, невозможно запросить представление для элемента списка, используемого для определенной позиции — его может не быть, и даже если он есть, этот элемент списка может вскоре быть повторно использован для новой позиции.

Также при наличии состояния, которое необходимо сохранить, его стоит сохранять в элементах модели, а не полагаться на виджеты, которые отображают эти элементы. Поскольку эти виджеты могут быть повторно использованы для новой позиции в любое время, что приведет к потере любого состояния.

Рассмотрим использование модели **ListModel** на примере виджета **ListBox**.

### Установка модели

Для установки модели в **ListBox** применяется функция **BindModel()**:

```c#
public void BindModel(ListModel? model, ListBoxCreateWidgetFunc? createWidgetFunc)
```

Параметры метода:

- model : представляет объект ListModel , который будет привязан к виджету. Может принимать значение null.

- createWidgetFunc : представляет делегат ListBoxCreateWidgetFunc ```c#
public delegate Widget ListBoxCreateWidgetFunc(Object item)
``` По сути это метод, который создает виджеты для элементов. Может принимать значение null.

Если виджет уже привязан к модели, то старая привязка уничтожается. Виджет очищается и заполняется новыми элементами из новой модели. Если же модель имеет значение null, то виджет остается пустым. Также стоит отметить, что виджет обновляется при каждом изменении модели.

Обратите внимание, что использование модели несовместимо с функциональностью фильтрации и сортировки в ListBox. При использовании модели фильтрация и сортировка должны быть реализованы моделью.

Для примера в качестве реализации модели возьмем тип **StringList**, который по сути представляет набор строк:

```c#
using Gtk;

var app= Application.New("com.enoobis", Gio.ApplicationFlags.DefaultFlags);

app.OnActivate += (sender, _) =>
{
    var window = new Window();
    window.Title = "enoobis.ru";
    window.DefaultWidth = 250;
    window.DefaultHeight = 200;

    // данные для списка
    string[] langs = {"C", "Python", "C++", "C#", "JavaScript", "Java"};
    // создаем StringList
    StringList model =  StringList.New(langs);

    var listBox = ListBox.New();
    listBox.BindModel(model, CreateRow);  // установка модели

    window.Child = listBox;
    window.Application = (Application) sender;
    window.Show();
};

app.RunWithSynchronizationContext(null); 

// создаем виджет
Widget CreateRow(Object item){

    StringObject strObj = (StringObject)item;
    // создаем строку для списка
    ListBoxRow row = ListBoxRow.New();
    // получаем текст из StringObject
    string text = strObj.GetString();
    // создаем метку для вывода в строке списка
    Label label = Label.New(text);
    label.Halign = Align.Start;
    // устанавливаем содержимое строки списка
    row.SetChild(label);
    return row;
}
```

Разберем основные моменты. Прежде всего создаем саму модель StringList:

```c#
string[] langs = {"C", "Python", "C++", "C#", "JavaScript", "Java"};
StringList model =  StringList.New(langs);
```

Для создания модели применяется статический метод `StringList.New()`, в который передается массив строк.

Далее после создания виджета устанавливаем для него модель:

```c#
var listBox = ListBox.New();
listBox.BindModel(model, CreateRow);
```

Второй параметр в `listBox.BindModel` в качестве фабрики элементов списка получает метод CreateRow. Так как каждый элемент виджета ListBox представляет объект ListBoxRow, а не простую строку. Соответственно нам нужна метод для конвертации типов:

```c#
Widget CreateRow(Object item){

    StringObject strObj = (StringObject)item;
    // создаем строку для списка
    ListBoxRow row = ListBoxRow.New();
    // получаем текст из StringObject
    string text = strObj.GetString();
    // создаем метку для вывода в строке списка
    Label label = Label.New(text);
    label.Halign = Align.Start;
    // устанавливаем содержимое строки списка
    row.SetChild(label);
    return row;
}
```

Метод CreateRow принимает через параметр item принимает элемент модели. В нашем случае модель - StringList, поэтому объект представляет тип `StringObject` - по сути некоторая обертка над строкой string. И чтобы получить значение `string`, применяем метод `strObj.GetString()`. В остальном действия метода CreateRow своядятся в преобразование из полученной строки в объект типа ListBoxRow. В итоге мы получим следующий список:

![подключение модели stringlist и listmodel к списку listbox в gtk](/uploads/course-lectures/8578ec3d94fbdfa7dd6a8cfebabd1e7a704c0f05.png)

Виджет ListView является мощным инструментом для отображения и управления списками данных в GTK. Он позволяет создать гибкие и функциональные списки, которые могут поддерживать различные виды взаимодействий, включая сортировку, фильтрацию и редактирование данных. Для создания виджета применяется статический метод **ListView.New()**



```c#

public static ListView New(SelectionModel? model, ListItemFactory? factory)
```



Этот метод принимает два параметра:





- model : используемая модель в виде объекта SelectionModel , который инкапсулирует данные списка. Может быть null

- factory : фабрика для заполнения элементов в виде объекта ListItemFactory . Может быть null



Основные свойства виджета:





- Factory : фабрика для заполнения элементов списка (объект ListItemFactory? ).

- Model : модель для отображаемых элементов (объект SelectionModel ).

- ShowSeparators : булевое свойство, устанавливает отображение разделителей между строками при значении true .

- SingleClickActivate : позволяет активировать строки по одному нажатию (при значении true ) и выбирать их при наведении.



Ключевыми элементами при создании виджета являются модель и фабрика элементов.



### SelectionModel



Модель с данными, с которой связывается виджет ListView, представляет интерфейс SelectionModel . GTK имеет три втроенных реализации этого интерфейса:





- MultiSelection : устанавливает поддержку множественного выбора

- SingleSelection : устанавливает поддержку одиночного выбора

- NoSelection : без поддержки выбора элементов



Таким образом, в зависимости от того, сколько элементов может выбирать пользователь, мы можем выбрать один из этих типов. Они создаются с помощью следующих статических методов, получая в качестве параметра модель - объект `ListModel`:



```c#

static SingleSelection.New(ListModel? model)

static MultiSelection.New(ListModel? model)

static NoSelection.New(ListModel? model)
```



Например, мы можем создать модель на основе массива строк:



```c#

// данные для списка
string[] langs = {"C", "Python", "C++", "C#", "JavaScript", "Java"};
// создаем StringList
StringList list =  StringList.New(langs);
SingleSelection model = SingleSelection.New(list)
```



В данном примере данные фактически представлены массивом langs. Сначала на основе этого списка создается объект `StringList`, который обертывает каждую строку в объект `StringObject`. Затем создаем объект `SingleSelection` (модель одиночного выбора) с помощью метода `SingleSelection.New()`, передавая в него модель строк.




### Создание фабрики элементов



Для отображения элементов модели в ListView применяется фабрика элементов - объект **ListItemFactory**. ListItemFactory отвечает за создание виджетов для элементов, взятых из модели. Каждый создаваемый фабрикой виджет представляет тип ListItem . Причем поскольку ListView отображает не весь список сразу, а только несколько элементов, то ListView дает указание ListItemFactory создать виджеты именно для этих элементов, которые отображаются в данный момент. По мере изменения модели списка или прокрутки списка пользователем элементы будут меняться, и ыиджет списка даст указание фабрике привязать ранее созданные виджеты к этим новым элементам.



Существуют различные реализации **ListItemFactory** для разных сценариев. Наиболее распространенными реализациями являются **BuilderListItemFactory**, которая для создания виджетов использует определение интерфейса в виде xml, и **SignalListItemFactory**, которая позволяет через обработку определенных событий сохранять полный контроль над тем, как виджеты настраиваются и управляются. Рассмотрим применение обеих фабрик.






#### Фабрика SignalListItemFactory



Фабрика **SignalListItemFactory** генерирует события для управления элементами списка. События генерируются для каждого элемента списка в следующем порядке:





- OnSetup : генерируется для настройки объекта ListItem. Обычно это означает создание виджетов, из которых будет состоять ListItem (например, вложенные метки) и добавление их в элемент списка. Эта настройка сохраняется, даже если экземпляр ListItem повторно используется (для привязки к другому элементу ListModel). ```c#
public event SignalHandler<SignalListItemFactory, SignalListItemFactory.SetupSignalArgs> OnSetup
```

- OnBind : генерируется для привязки элемента в модели списка к виджету, созданному на предыдущем шаге. Для получения элемента применяется свойство item объекта ListItem. Этот событие также генерируется, когда ListItem создается заново или когда с элементом списка происходят какие-то изменения. ```c#
public event SignalHandler<SignalListItemFactory, SignalListItemFactory.BindSignalArgs> OnBind
```

- OnUnbind : генерируется для отмены всего, что сделано на предыдущем шаге. Обычно это означает отключение обработчиков событий. После вызова этого события ListItem больше не будет использоваться в виджете списка. ```c#
public event SignalHandler<SignalListItemFactory, SignalListItemFactory.UnbindSignalArgs> OnUnbind
```

- OnBind и OnUnbind могут генерироваться повторно множество раз, чтобы связать ListItem для использования с новыми элементами. Повторное использование ListItem позволяет избежать потенциально затратной настройки.

- OnTeardown : генерируется для удаления ListItem будет уничтожен и больше не будет использоваться. ```c#
public event SignalHandler<SignalListItemFactory, SignalListItemFactory.TeardownSignalArgs> OnTeardown
```



Стоит отметить, что в качестве второго параметра в метод-обработчик этих событий передается объект аргумента типа `SignalListItemFactory.SetupSignalArgs` или `SignalListItemFactory.BindSignalArgs` и т.д. У этого объекта есть свойство `Object`, которое представляет тип `GObject.Object` и которое по сути и представляет элемент списка - объект ListItem.




Рассмотрим на примере:



```c#

using Gtk;

var app= Application.New("com.enoobis", Gio.ApplicationFlags.DefaultFlags);

app.OnActivate += (sender, _) =>
{
    var window = new Window();
    window.Title = "enoobis.ru";
    window.DefaultWidth = 250;
    window.DefaultHeight = 200;
   
    // данные для списка
    string[] langs = {"C", "Python", "C++", "C#", "JavaScript", "Java"};
    // создаем StringList
    StringList list =  StringList.New(langs);
    // создаем SingleSelection
    SingleSelection model = SingleSelection.New(list);

    // Создание фабрики для элементов списка
    SignalListItemFactory factory = SignalListItemFactory.New();
    factory.OnSetup += SetupListitem;
    factory.OnBind += BindListitem;
    // установка следующих событий не нужна и приведена только для демонстрации
    factory.OnUnbind += UnbindListitem;
    factory.OnTeardown += TeardownListitem;

    // Создание ListView
    ListView listView = ListView.New(model, factory);

    window.Child = listView;
    window.Application = (Application) sender;
    window.Show();
};

app.RunWithSynchronizationContext(null); 

void SetupListitem (SignalListItemFactory factory, SignalListItemFactory.SetupSignalArgs e)
{
    ListItem listitem = (ListItem) e.Object;
    Label label = Label.New(null);
    label.Halign = Align.Start;
    listitem.SetChild(label);
}

void BindListitem (SignalListItemFactory factory, SignalListItemFactory.BindSignalArgs e)
{
    ListItem listitem = (ListItem) e.Object;
    Label? label = (Label?) listitem.GetChild();
    // получаем данные из модели
    if(listitem.Item != null && label != null){
        StringObject strobj = (StringObject)listitem.Item;
        label.Label_ = strobj.GetString();  // устанавливаем по этим данным текст метки
    } 
}

void UnbindListitem (SignalListItemFactory self, SignalListItemFactory.UnbindSignalArgs e) {
  // здесь ничего не делаем
}

void TeardownListitem(SignalListItemFactory self, SignalListItemFactory.TeardownSignalArgs e) {
  // здесь также ничего не делаем
  // ListItem вскоре будет удален. Явным образом его удалять или устанавливать в null его дочерний виджет не надо
}
```



