Аналогичным образом можно было бы создавать деревья с более глубокой вложенностью. Например, пусть у нас будет следующий метод CreateFunc для определения модели:



```c#

Gio.ListModel? CreateFunc(Object item)
{
    // получаем элемент из корневой модели
    StringObject strobj = (StringObject)item;
    // получаем сам текст
    string parent = strobj.GetString();

    // дочерняя модель для каждого элемента корневой модели
    StringList child_list = StringList.New(null);

    // Добавляем дочерние элементы в зависимости от родителя
    if (parent.CompareTo("Категория 1")==0) 
    {
        child_list.Append("Подкатегория 1.1");
        child_list.Append("Подкатегория 1.2");
    } 
    else if(parent.CompareTo("Категория 2")==0) 
    {
        child_list.Append("Подкатегория 2.1");
        child_list.Append("Подкатегория 2.2");
        child_list.Append("Подкатегория 2.3");
    }
    else if (parent.CompareTo("Подкатегория 1.2")==0) 
    {
        child_list.Append("Подподкатегория 1.2.1");
        child_list.Append("Подподкатегория 1.2.2");
        child_list.Append("Подподкатегория 1.2.3");
    }
    else return null; // если для элемента не нужна дочерняя модель и у него нет вложенных элементов

    return child_list;
}
```



Тогла вторая подкатегория первой категории также будет представлять разворачиваемый узел:



